1	{
2	  "name": "harbor-dispatch",
3	  "version": "3.4.0",
4	  "private": true,
5	  "description": "Berth planning, cargo manifests and arrival estimates for terminal operations",
6	  "type": "module",
7	  "engines": {
8	    "node": ">=26"
9	  },
10	  "scripts": {
11	    "test": "node --test",
12	    "check": "node tools/codegen.mjs --verify && node --import ./tools/aliases.mjs --test",
13	    "codegen": "node tools/codegen.mjs"
14	  }
15	}
