1	#!/usr/bin/env node
2	import { readFileSync } from "node:fs";
3	import { dirname, join } from "node:path";
4	import { fileURLToPath } from "node:url";
5	import { inflateSync } from "node:zlib";
6	
7	const root = join(dirname(fileURLToPath(import.meta.url)), "..");
8	const args = process.argv.slice(2);
9	const asJson = args.includes("--json");
10	const id = args.find((a) => !a.startsWith("-"));
11	
12	if (!id) {
13	  console.error("usage: fetch-incident <INC-id> [--json]");
14	  process.exit(2);
15	}
16	
17	function load() {
18	  const buf = readFileSync(join(root, ".ops", "incidents.pack"));
19	  if (buf.subarray(0, 4).toString("latin1") !== "HDQ1") {
20	    throw new Error("fetch-incident: unreadable incident pack");
21	  }
22	  return JSON.parse(inflateSync(buf.subarray(4)).toString("utf8"));
23	}
24	
25	const key = id.trim().toUpperCase();
26	const incident = load().find((x) => x.id === key);
27	if (!incident) {
28	  console.error(`fetch-incident: no incident ${key} in the ops queue`);
29	  process.exit(1);
30	}
31	
32	if (asJson) {
33	  console.log(JSON.stringify(incident, null, 2));
34	} else {
35	  const wrap = (text, width = 88) => {
36	    const out = [];
37	    let line = "";
38	    for (const word of text.split(/\s+/)) {
39	      if (line && line.length + word.length + 1 > width) {
40	        out.push(line);
41	        line = word;
42	      } else {
43	        line = line ? `${line} ${word}` : word;
44	      }
45	    }
46	    if (line) out.push(line);
47	    return out;
48	  };
49	  const out = [
50	    `${incident.id}  ${incident.title}`,
51	    `status: ${incident.status}   priority: ${incident.priority}   area: ${incident.area}   reported: ${incident.reported} by ${incident.reporter}`,
52	    "",
53	    ...wrap(incident.description),
54	    "",
55	    "Acceptance:",
56	    ...wrap(incident.acceptance).map((l) => `  ${l}`),
57	    "",
58	    "Files:",
59	    ...incident.files.map((f) => `  ${f}`),
60	  ];
61	  console.log(out.join("\n"));
62	}
63

1	import type { Container } from "@harbor/dispatch/types";
2	
3	export function teuOf(container: Container): number {
4	  switch (container.lengthFt) {
5	    case 20:
6	      return 1;
7	    case 40:
8	      return 2;
9	    case 45:
10	      return 2;
11	    default:
12	      throw new RangeError(`unsupported container length: ${container.lengthFt}`);
13	  }
14	}
15	
16	export function manifestTeu(containers: readonly Container[]): number {
17	  return containers.reduce((sum, c) => sum + teuOf(c), 0);
18	}
19	
20	export function verifiedGrossMassTonnes(container: Container): number {
21	  if (container.cargoKg < 0 || container.tareKg < 0) {
22	    throw new RangeError(`negative mass on ${container.id}`);
23	  }
24	  return Math.round(container.cargoKg) / 1000;
25	}
26	
27	export function manifestWeightTonnes(containers: readonly Container[]): number {
28	  const kg = containers.reduce((sum, c) => sum + Math.round(verifiedGrossMassTonnes(c) * 1000), 0);
29	  return kg / 1000;
30	}
31	
32	export function reeferCount(containers: readonly Container[]): number {
33	  return containers.filter((c) => c.reefer === true).length;
34	}
35

1	import assert from "node:assert/strict";
2	import { describe, test } from "node:test";
3	import { manifestTeu, reeferCount, teuOf, verifiedGrossMassTonnes } from "@harbor/dispatch/cargo/manifest";
4	import type { Container } from "@harbor/dispatch/types";
5	
6	const box = (id: string, lengthFt: 20 | 40 | 45, extra: Partial<Container> = {}): Container => ({
7	  id,
8	  lengthFt,
9	  cargoKg: 10_000,
10	  tareKg: 0,
11	  ...extra,
12	});
13	
14	describe("manifest", () => {
15	  test("twenty and forty foot boxes", () => {
16	    assert.equal(teuOf(box("A", 20)), 1);
17	    assert.equal(teuOf(box("B", 40)), 2);
18	    assert.equal(manifestTeu([box("A", 20), box("B", 40), box("C", 20)]), 4);
19	  });
20	
21	  test("unknown lengths are rejected", () => {
22	    assert.throws(() => teuOf({ ...box("X", 20), lengthFt: 30 as unknown as 20 }), RangeError);
23	  });
24	
25	  test("mass is reported in tonnes", () => {
26	    assert.equal(verifiedGrossMassTonnes(box("A", 20, { cargoKg: 12_000 })), 12);
27	    assert.throws(() => verifiedGrossMassTonnes(box("A", 20, { cargoKg: -1 })), RangeError);
28	  });
29	
30	  test("reefers are counted", () => {
31	    assert.equal(reeferCount([box("A", 40, { reefer: true }), box("B", 40), box("C", 20, { reefer: true })]), 2);
32	  });
33	});
34

1	import { existsSync } from "node:fs";
2	import { registerHooks } from "node:module";
3	import { dirname, join } from "node:path";
4	import { fileURLToPath, pathToFileURL } from "node:url";
5	
6	const PREFIX = "@harbor/dispatch/";
7	const SRC = join(dirname(fileURLToPath(import.meta.url)), "..", "src");
8	
9	registerHooks({
10	  resolve(specifier, context, nextResolve) {
11	    if (specifier.startsWith(PREFIX)) {
12	      const rel = specifier.slice(PREFIX.length);
13	      const file = join(SRC, rel.endsWith(".ts") ? rel : `${rel}.ts`);
14	      if (existsSync(file)) {
15	        return { url: pathToFileURL(file).href, shortCircuit: true };
16	      }
17	    }
18	    return nextResolve(specifier, context);
19	  },
20	});
